WITH dim_totals AS (SELECT o.status AS order_status, s.carrier, COUNT(*) AS rows_total, MAX(s.cost) AS max_cost, GROUPING_ID() AS level_id FROM shipments s INNER JOIN orders o ON s.order_id = o.id GROUP BY ROLLUP (o.status, s.carrier)) SELECT order_status, max_cost, level_id, CASE WHEN order_status RLIKE '^(RETURNED|PENDING)$' THEN 'GROUP_B' WHEN order_status RLIKE '^(COMPLETED|CANCELLED)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS order_status_zone FROM dim_totals ORDER BY max_cost DESC, level_id
